import{_ as d,o as e,c as r,a4 as a}from"./chunks/framework.BMj-uaUw.js";const u=JSON.parse('{"title":"前端学习路线","description":"","frontmatter":{},"headers":[{"level":2,"title":"第一阶段 · 打地基","slug":"第一阶段-·-打地基","link":"#第一阶段-·-打地基","children":[]},{"level":2,"title":"第二阶段 · 上装备","slug":"第二阶段-·-上装备","link":"#第二阶段-·-上装备","children":[]},{"level":2,"title":"第三阶段 · 定方向","slug":"第三阶段-·-定方向","link":"#第三阶段-·-定方向","children":[]},{"level":2,"title":"一句话说清三个阶段的关系","slug":"一句话说清三个阶段的关系","link":"#一句话说清三个阶段的关系","children":[]},{"level":2,"title":"给学生的几句实话","slug":"给学生的几句实话","link":"#给学生的几句实话","children":[]},{"level":2,"title":"自测：你现在在哪一站","slug":"自测-你现在在哪一站","link":"#自测-你现在在哪一站","children":[]}],"relativePath":"guide/learning-path.md","filePath":"guide/learning-path.md","lastUpdated":1789307994000}'),o={name:"guide/learning-path.md"};function n(l,t,i,s,h,p){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="前端学习路线" tabindex="-1">前端学习路线 <a class="header-anchor" href="#前端学习路线" aria-label="Permalink to &quot;前端学习路线&quot;">​</a></h1><p>学前端最常见的问题不是不努力，而是<strong>不知道自己站在路线的哪个位置</strong> —— 于是今天看 Vue，明天看 React， 后天听说 TypeScript 重要又去翻两天。每样都碰过，每样都做不出东西。</p><p>这一页给你一条完整路线，把前端学习拆成三个阶段，并标出本课程的位置。看完你应该能回答两个问题： <strong>我现在在哪一站，下一站该做什么。</strong></p><h2 id="第一阶段-·-打地基" tabindex="-1">第一阶段 · 打地基 <a class="header-anchor" href="#第一阶段-·-打地基" aria-label="Permalink to &quot;第一阶段 · 打地基&quot;">​</a></h2><p><strong>目标：能用原生技术做出会动的页面。</strong> 对应先修课程，约 60 - 80 学时。</p><p>这一阶段的共同点是：<strong>不依赖任何框架</strong>。为什么必须先打地基？因为框架解决的是&quot;怎么组织代码&quot;的问题， 如果连基础的 DOM 操作和异步都没写过，你没法判断框架帮你省掉了什么，只能靠死记 API。</p><table tabindex="0"><thead><tr><th>能力项</th><th>过关标准</th><th>怎么自检</th></tr></thead><tbody><tr><td>HTML</td><td>能凭记忆写出语义化结构，知道表单、列表、表格的常用属性</td><td>给一张设计图，不查资料写出结构骨架</td></tr><tr><td>CSS</td><td>能独立完成响应式布局，理解 Flex 与 Grid、盒模型、层叠与优先级</td><td>不借助框架，做一个手机和电脑都能看的页面</td></tr><tr><td>JavaScript</td><td>掌握变量、函数、数组与对象方法、ES6 模块、异步（Promise 与 async / await）</td><td>手写一个带分页的数据筛选，用 fetch 拿数据</td></tr><tr><td>DOM 与调试</td><td>会用开发者工具定位样式与脚本问题，看得懂控制台报错</td><td>看到一个报错，能说出它在哪一行、大概什么原因</td></tr><tr><td>工具初识</td><td>装好编辑器、会开浏览器控制台、知道 Git 是什么</td><td>—</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">别急着跳过</p><p>&quot;我看过 JS 教程&quot;和&quot;我能用 JS 写出东西&quot;是两件事。第一阶段的过关标准统一是<strong>能独立做出来</strong>， 不是看得懂。如果上面的自检题有一半做不出来，先回去补 —— 这门课不会停下来讲 <code>const</code> 和 <code>for</code> 循环。</p></div><h2 id="第二阶段-·-上装备" tabindex="-1">第二阶段 · 上装备 <a class="header-anchor" href="#第二阶段-·-上装备" aria-label="Permalink to &quot;第二阶段 · 上装备&quot;">​</a></h2><p><strong>目标：用现代工程化方式做项目。</strong> 这就是本课程的 48 学时。</p><table tabindex="0"><thead><tr><th>能力项</th><th>过关标准</th><th>对应单元</th></tr></thead><tbody><tr><td>工程化认知</td><td>能说清工程化解决了哪几类问题，知道一个现代前端项目的标准结构</td><td>单元 1</td></tr><tr><td>工具链</td><td>能独立初始化工程、读懂 <code>package.json</code>、配置 Vite、接上规范与提交钩子</td><td>单元 2 - 3</td></tr><tr><td>框架核心</td><td>会用组合式 API 写出响应式交互，能独立排查&quot;数据不更新&quot;一类问题</td><td>单元 4 - 6</td></tr><tr><td>组件化</td><td>能按职责拆分组件、设计 props 与事件接口、用插槽提高复用度</td><td>单元 7 - 8</td></tr><tr><td>应用架构</td><td>能用路由与状态管理组织多页面应用，封装请求层，实现登录鉴权</td><td>单元 9 - 10</td></tr><tr><td>交付能力</td><td>能打包、部署、写交接文档、在答辩中讲清技术决策</td><td>单元 11 - 12</td></tr></tbody></table><p>这一阶段有一个明显的转折：<strong>从&quot;写页面&quot;变成&quot;搭工程&quot;</strong>。</p><p>在第一阶段，你写的是一个 HTML 文件加一个 JS 文件；在第二阶段，你要管的是几十个源文件、 一份依赖清单、一堆配置，还要保证同事拉下来能跑起来。难度不在于语法变难了，而在于<strong>要考虑的东西变多了</strong>。</p><h2 id="第三阶段-·-定方向" tabindex="-1">第三阶段 · 定方向 <a class="header-anchor" href="#第三阶段-·-定方向" aria-label="Permalink to &quot;第三阶段 · 定方向&quot;">​</a></h2><p><strong>目标：按岗位方向深入。</strong> 对应后续课程与自主学习，建议 60 学时以上。</p><p>到这一步，基础能力和工程能力都已经具备，接下来是选一条路走深。</p><table tabindex="0"><thead><tr><th>方向</th><th>主攻内容</th><th>典型出口</th></tr></thead><tbody><tr><td>业务开发</td><td>组件库二次封装、复杂表单与表格、权限体系、性能优化、TypeScript</td><td>后台管理系统、企业信息化前端</td></tr><tr><td>跨端开发</td><td>uni-app 或 Taro、小程序规范、多端适配与条件编译、原生能力调用</td><td>小程序、移动端 H5、混合应用</td></tr><tr><td>服务端渲染</td><td>Nuxt 路由与数据获取、SSR 与预渲染、SEO、部署到 Node 服务</td><td>官网、内容型站点、电商前台</td></tr><tr><td>质量与工程</td><td>Vitest 单元测试、Playwright 端到端测试、CI 流水线、监控与埋点</td><td>测试开发、前端基础设施</td></tr><tr><td>可视化</td><td>ECharts、Canvas 与 WebGL、大屏适配、数据看板</td><td>数据可视化、BI 前端</td></tr></tbody></table><p>本课程在<a href="/frontend-engineering-course/unit12/">单元 12</a> 之后给了一个课外拓展：用 uni-app 把项目里的两个页面移植到移动端。 不占课内学时，是给想往跨端方向走的同学留的入口。</p><h2 id="一句话说清三个阶段的关系" tabindex="-1">一句话说清三个阶段的关系 <a class="header-anchor" href="#一句话说清三个阶段的关系" aria-label="Permalink to &quot;一句话说清三个阶段的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>解决的问题</th><th>关键词</th></tr></thead><tbody><tr><td>打地基</td><td>能不能做出东西</td><td>语言、DOM、调试</td></tr><tr><td>上装备</td><td>能不能做出<strong>能交付</strong>的东西</td><td>工程、框架、协作</td></tr><tr><td>定方向</td><td>能不能做出<strong>别人做不了</strong>的东西</td><td>深度、领域、性能</td></tr></tbody></table><h2 id="给学生的几句实话" tabindex="-1">给学生的几句实话 <a class="header-anchor" href="#给学生的几句实话" aria-label="Permalink to &quot;给学生的几句实话&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">别把路线背下来</p><p>按&quot;能做出东西&quot;的标准往下一站走就够了。路线图是给自己定位用的，不是考试大纲。</p></div><p><strong>框架会换，底层能力不会换。</strong></p><p>Vue 2 换到 Vue 3、Vue 换到 React，语法差异一两周就能适应。但 Node 生态怎么运作、模块化怎么组织、 怎么调试一个问题、代码怎么分层 —— 这些东西十年没怎么变，值得花时间。</p><p><strong>官方文档是第一优先级。</strong></p><p>遇到问题的查找顺序应该是：官方文档 → 搜索引擎 → 问人。原因很简单：文档写的是设计意图， 搜到的答案多数是&quot;别人踩坑后的权宜之计&quot;，可能已经过时。</p><p><strong>&quot;看得懂&quot;不算过关。</strong></p><p>路线图上任何一站的过关标准都是<strong>能独立做出来，并且讲清楚为什么这么做</strong>。 对着教程敲一遍能跑，关上教程写不出来，说明还没过关。</p><h2 id="自测-你现在在哪一站" tabindex="-1">自测：你现在在哪一站 <a class="header-anchor" href="#自测-你现在在哪一站" aria-label="Permalink to &quot;自测：你现在在哪一站&quot;">​</a></h2><ul><li>能不看资料写出一个带表单校验的页面吗？→ 不能，在第一阶段。</li><li>能说清 <code>package.json</code> 里 <code>dependencies</code> 和 <code>devDependencies</code> 的区别吗？→ 不能，准备进第二阶段。</li><li>换台电脑，能让你的项目在 15 分钟内跑起来吗？→ 不能，第二阶段的工程能力还没到位。</li><li>能解释你的页面为什么这么分层、这么拆组件吗？→ 不能，还在&quot;能写&quot;和&quot;会设计&quot;之间。</li><li>能独立排查一个线上白屏问题吗？→ 不能，第三阶段还没开始。</li></ul><p>对应地，往下读：</p><ul><li><a href="/frontend-engineering-course/unit01/">单元 1：工程化认知与开发环境</a></li><li><a href="/frontend-engineering-course/guide/roadmap.html">课程地图：12 周讲什么</a></li><li><a href="/frontend-engineering-course/guide/environment.html">开发环境准备</a></li></ul>',32)])])}const g=d(o,[["render",n]]);export{u as __pageData,g as default};
